    """
    Returns a list where index i is the number of days to wait after day i
    to get a strictly warmer temperature (or 0 if none).
    """
    n = len(temps)
    result = [0] * n
    for i in range(n):
        for j in range(i + 1, n):
            if temps[j] > temps[i]:
                result[i] = j - i
                break
        else:
